   189	export async function activate(context: vscode.ExtensionContext) {
   190		extensionContext = context;
   191	
   192		// pi's InteractiveMode ends every quit path (/quit, Ctrl+C/Ctrl+D, signals)
   193		// with process.exit(). VS Code's extension host already neutralizes
   194		// process.exit (patchProcess in extensionHostProcess.ts — it just logs
   195		// "prevented"), so the host survives but our TUI tab is left open with a
   196		// dead session behind it. Intercept instead: when pi asks to exit, close
   197		// the session panel(s) — /quit or closing the tab are the only sanctioned
   198		// ways to end a session. Per-session targeting uses WebviewPty.quitting
   199		// (set when pi's shutdown calls drainInput).
   200		const baseExit = process.exit.bind(process);
   201		(process as unknown as { exit: (code?: number) => never }).exit = ((
   202			code?: number,
   203		) => {
   204			if (sessions.size === 0) {
   205				// Not a CodePi shutdown — let VS Code's own patch handle it.
   206				baseExit(code);
   207				return;
   208			}
   209			const quitting = [...sessions.values()].filter(
   210				(s) => (s.pty as WebviewPty).quitting,
   211			);
   212			const targets = quitting.length > 0 ? quitting : [...sessions.values()];
   213			console.log(
   214				`[CodePi] pi requested process.exit(${code}) — closing ${targets.length} TUI panel(s)`,
   215			);
   216			for (const s of targets) {
   217				if (sessions.has(s.sessionId)) cleanupSession(s.sessionId);
   218			}
   219			// Swallow: pi's shutdown() returns normally and the host keeps running.
   220		}) as (code?: number) => never;
   221	
   222		// The embedded TUI renders in a truecolor-capable webview xterm. pi's
   223		// terminal capability detection (pi-tui detectCapabilities) only emits
   224		// truecolor when it can identify a truecolor terminal — otherwise every
   225		// theme hex color gets quantized to the 256-color palette, which makes
   226		// the dark message/tool backgrounds render as near-black. Identify the
   227		// "terminal" as VS Code (TERM_PROGRAM=vscode ⇒ trueColor + OSC8 links)
   228		// and also set COLORTERM as a belt-and-suspenders; getCapabilities()
   229		// caches, so this must run before ANY pi SDK call.
   230		process.env.TERM_PROGRAM = "vscode";
   231		process.env.COLORTERM = "truecolor";
   232	
   233		// Point pi's config and user-resource storage at the executing computer's
   234		// canonical ~/.pi/agent. Must run before any SDK call — pi reads
   235		// PI_CODING_AGENT_DIR at call time.
   236		const agentDir = getCanonicalAgentDir();
   237		setAgentDir(agentDir);
   238		fs.mkdirSync(agentDir, { recursive: true });
   239	
   240		// Copilot-style pending-edit dot on tabs/Explorer for files awaiting review.
   241		registerPendingReviewDots(extensionContext);
   242	
   243		// Keep CodePi conversations in VS Code storage, separate from Pi's
   244		// canonical ~/.pi/agent resources and sessions.
   245		codePiSessionDir = getCodePiSessionDir(context.globalStorageUri.fsPath);
   246		fs.mkdirSync(codePiSessionDir, { recursive: true });
   247		await offerLegacyMigration(context, agentDir, codePiSessionDir);
   248	
   249		// Register session tree provider
   250		treeProvider = new SessionTreeProvider(codePiSessionDir);
   251		const treeView = vscode.window.createTreeView("codepi.sessionsList", {
   252			treeDataProvider: treeProvider,
   253			showCollapseAll: false,
   254		});
   255		context.subscriptions.push(treeView);
   256	
   257		// Restore TUI tabs that were open before a window reload. VS Code persists
   258		// open webview panels and revives them here; the webview content persisted
   259		// its session id via vscode.setState (see terminal.ts), which arrives as
   260		// `state` below.
   261		context.subscriptions.push(
   262			vscode.window.registerWebviewPanelSerializer("codepi-tui", {
   263				deserializeWebviewPanel: async (panel, state) => {
   264					const sessionId = (state as { sessionId?: string } | undefined)
   265						?.sessionId;
   266					if (!sessionId) {
   267						panel.dispose();
   268						return;
   269					}
   270					try {
   271						const sessionPath = await findSessionPathById(sessionId);
   272						if (!sessionPath) {
   273							// Session deleted since the reload — drop the orphaned tab.
   274							panel.dispose();
   275							return;
   276						}
   277						const pi = await getPi();
   278						const sessionManager = pi.SessionManager.open(
   279							sessionPath,
   280							getCodePiSessionDirForRuntime(),
   281							getWorkspaceRoot(),
   282						);
   283						if (sessionManager.getSessionId() !== sessionId) {
   284							panel.dispose();
   285							return;
   286						}
   287						await setupSessionPanel(
   288							panel,
   289							sessionManager,
   290							sessionId,
   291							sessionPath,
   292						);
   293					} catch (err) {
   294						console.error(
   295							"[CodePi] Failed to restore session",
   296							sessionId,
   297							":",
   298							err,
   299						);
   300						panel.dispose();

