341	/** Detect existing config in a legacy agent dir (e.g. ~/.pi/agent). */
342	export function detectLegacyConfig(
343		legacyAgentDir: string,
344	): LegacyConfigDetected | undefined {
345		const found: LegacyConfigDetected = {
346			settings: existsSync(join(legacyAgentDir, "settings.json")),
347			auth: existsSync(join(legacyAgentDir, "auth.json")),
348			models: existsSync(join(legacyAgentDir, "models.json")),
349		};
350		return found.settings || found.auth || found.models ? found : undefined;
351	}
352	
353	export interface MigrationResult {
354		copiedFiles: string[];
355		copiedSessions: string[];
356		skippedFiles: string[];
357		sessionsSkipped?: "missing-source" | "destination-not-empty";
358	}
359	
360	/**
361	 * Migrate storage written by older CodePi versions.
362	 *
363	 * The source session directory is passed explicitly because the canonical Pi
364	 * agent directory may also contain Pi CLI sessions. This helper never derives
365	 * or inspects `<canonicalAgentDir>/sessions`.
366	 */
367	export function migrateLegacyCodePiStorage(
368		legacyAgentDir: string,
369		canonicalAgentDir: string,
370		legacySessionDir: string,
371		codePiSessionDir: string,
372	): MigrationResult {
373		mkdirSync(canonicalAgentDir, { recursive: true });
374		const copiedFiles: string[] = [];
375		const skippedFiles: string[] = [];
376		for (const file of ["settings.json", "auth.json", "models.json"]) {
377			const source = join(legacyAgentDir, file);
378			const target = join(canonicalAgentDir, file);
379			if (!existsSync(source) || !statSync(source).isFile()) continue;
380			if (existsSync(target)) {
381				skippedFiles.push(file);
382				continue;
383			}
384			cpSync(source, target);
385			if (file === "auth.json") {
386				try {
387					chmodSync(target, 0o600);
388				} catch {
389					/* non-POSIX — ignore */
390				}
391			}
392			copiedFiles.push(file);
393		}
394	
395		if (
396			!existsSync(legacySessionDir) ||
397			!statSync(legacySessionDir).isDirectory()
398		) {
399			return {
400				copiedFiles,
401				copiedSessions: [],
402				skippedFiles,
403				sessionsSkipped: "missing-source",
404			};
405		}
406		mkdirSync(codePiSessionDir, { recursive: true });
407		if (readdirSync(codePiSessionDir).length > 0) {
408			return {
409				copiedFiles,
410				copiedSessions: [],
411				skippedFiles,
412				sessionsSkipped: "destination-not-empty",
413			};
414		}
415		cpSync(legacySessionDir, codePiSessionDir, { recursive: true });
416		const copiedSessions = readdirSync(legacySessionDir);
417		return { copiedFiles, copiedSessions, skippedFiles };
418	}
125	const LEGACY_MIGRATION_PROMPTED_KEY = "codepi.legacyMigrationPrompted.v1";
126	
127	async function offerLegacyMigration(
128		context: vscode.ExtensionContext,
129		canonicalAgentDir: string,
130		codePiSessionDir: string,
131	): Promise<void> {
132		if (context.globalState.get<boolean>(LEGACY_MIGRATION_PROMPTED_KEY)) return;
133	
134		const legacyAgentDir = path.join(context.globalStorageUri.fsPath, "agent");
135		const legacySessionDir = path.join(legacyAgentDir, "sessions");
136		const detected = detectLegacyConfig(legacyAgentDir);
137		const hasMissingConfig = Boolean(
138			detected &&
139				(["settings", "auth", "models"] as const).some(
140					(file) =>
141						detected[file] &&
142						!fs.existsSync(path.join(canonicalAgentDir, `${file}.json`)),
143				),
144		);
145		const hasLegacySessions =
146			fs.existsSync(legacySessionDir) &&
147			fs.statSync(legacySessionDir).isDirectory() &&
148			fs.readdirSync(legacySessionDir).length > 0 &&
149			(!fs.existsSync(codePiSessionDir) ||
150				fs.readdirSync(codePiSessionDir).length === 0);
151		if (!hasMissingConfig && !hasLegacySessions) {
152			await context.globalState.update(LEGACY_MIGRATION_PROMPTED_KEY, true);
153			return;
154		}
155	
156		const choice = await vscode.window.showInformationMessage(
157			"CodePi found settings from an older CodePi storage location. Migrate missing files from the old CodePi storage into this computer's ~/.pi/agent? CodePi sessions move only within this computer's VS Code storage; remote hosts are not affected, and ~/.pi/agent/sessions is never copied.",
158			"Migrate now",
159			"Not now",
160		);
161		await context.globalState.update(LEGACY_MIGRATION_PROMPTED_KEY, true);
162		if (choice !== "Migrate now") return;
163	
164		try {
165			const result = migrateLegacyCodePiStorage(
166				legacyAgentDir,
167				canonicalAgentDir,
168				legacySessionDir,
169				codePiSessionDir,
170			);
171			const copied = [
172				...result.copiedFiles,
173				...result.copiedSessions.map((name) => `sessions/${name}`),
174			];
175			vscode.window.showInformationMessage(
176				copied.length > 0
177					? `CodePi migrated ${copied.join(", ")} from its legacy storage.`
178					: "CodePi found no additional legacy files to migrate.",
179			);
180		} catch (error) {
181			vscode.window.showErrorMessage(
182				`CodePi could not migrate legacy storage: ${error instanceof Error ? error.message : String(error)}`,
183			);
184		}
185	}

